function articleDateValue(value){const m=String(value||'').trim().toLocaleLowerCase('ro').match(/^(\d{1,2})\s+([a-zăâîșț]+)\s+(\d{4})$/u);if(!m)return 0;const month=ARTICLE_MONTHS[m[2]];return month?Date.UTC(Number(m[3]),month-1,Number(m[1])):0;}
ARTICLES.sort((a,b)=>articleDateValue(b.date)-articleDateValue(a.date));

